def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find the longest contiguous non-background run: this is the pattern.
    best = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            start = c
            while c < w and row[c] != bg:
                c += 1
            if best is None or c - start > best[2] - best[1]:
                best = (r, start, c)

    if best is None:
        return [row[:] for row in grid]
    r0, start, end = best
    pattern = grid[r0][start:end]
    pattern_colors = set(pattern)
    marker_colors = [v for v in counts if v != bg and v not in pattern_colors]
    if not marker_colors:
        return [row[:] for row in grid]
    marker = max(marker_colors, key=lambda v: counts[v])

    out = [row[:] for row in grid]
    center = len(pattern) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, value in enumerate(pattern):
                    x = c + i - center
                    if 0 <= x < w:
                        out[r][x] = value
    return out
